const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const {execFileSync} = require('node:child_process');
const ts = require('typescript');
const {App} = require('aws-cdk-lib');
const {Template} = require('aws-cdk-lib/assertions');
const file = path.resolve('src/stack.ts');
function synth(source) {
  const compiled = ts.transpileModule(source, {compilerOptions: {module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022}}).outputText;
  const mod = new Module(file, module);
  mod.filename = file;
  mod.paths = Module._nodeModulePaths(path.dirname(file));
  mod._compile(compiled, file);
  return Template.fromStack(new mod.exports.GenuiFoundation(new App(), 'IndependentSchedulerReview')).toJSON();
}
const before = synth(execFileSync('git', ['show', 'HEAD:infra/src/stack.ts'], {encoding: 'utf8'}));
const after = synth(fs.readFileSync(file, 'utf8'));
const previous = before.Outputs.DeploymentExpiryScheduleArn.Value;
const current = after.Outputs.DeploymentExpiryScheduleArn.Value;
assert.ok(previous['Fn::GetAtt']);
assert.ok(current['Fn::Join']);
assert.notDeepEqual(previous, current);
delete before.Outputs.DeploymentExpiryScheduleArn;
delete after.Outputs.DeploymentExpiryScheduleArn;
assert.deepEqual(after, before);
console.log(JSON.stringify({passed:true, unchanged_outside:'Outputs.DeploymentExpiryScheduleArn', resource_count:Object.keys(after.Resources).length, old_value:previous, new_value:current}));
